// ── Command Palette ──────────────────────────────────────────────────────────────
function CommandPalette({open,onClose,sections,onNavigate,t}){const[query,setQuery]=useState("");const inputRef=useRef(null);useEffect(()=>{if(open){setQuery("");setTimeout(()=>inputRef.current?.focus(),50);}},[open]);useEffect(()=>{const h=e=>{if(e.key==="Escape")onClose();};window.addEventListener("keydown",h);return()=>window.removeEventListener("keydown",h);},[onClose]);const allItems=sections.flatMap(s=>s.tabs.map(tab=>({sectionId:s.id,sectionLabel:s.label,tabId:tab.id,tabLabel:tab.label})));const filtered=query?allItems.filter(i=>i.tabLabel.toLowerCase().includes(query.toLowerCase())||i.sectionLabel.toLowerCase().includes(query.toLowerCase())):allItems;if(!open)return null;return <div onClick={onClose} style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.6)",zIndex:1000,display:"flex",alignItems:"flex-start",justifyContent:"center",paddingTop:80,backdropFilter:"blur(4px)"}}><div onClick={e=>e.stopPropagation()} style={{background:t.isDark?"#0e1628":"#fff",border:`1px solid ${t.border}`,borderRadius:16,width:"min(520px,92vw)",overflow:"hidden",boxShadow:"0 20px 60px rgba(0,0,0,0.5)",animation:"fadeIn 0.15s ease-out"}}><div style={{padding:"11px 14px",borderBottom:`1px solid ${t.sep}`,display:"flex",alignItems:"center",gap:10}}><span style={{fontSize:16,opacity:0.6}}>🔍</span><input ref={inputRef} value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search sections..." style={{flex:1,background:"none",border:"none",outline:"none",color:t.text,fontSize:15,fontFamily:FONT}}/><span style={{fontSize:10,color:t.sub,background:t.isDark?"rgba(255,255,255,.05)":"rgba(0,0,0,.05)",borderRadius:5,padding:"2px 6px"}}>ESC</span></div><div style={{maxHeight:380,overflowY:"auto"}}>{filtered.length===0&&<div style={{padding:24,textAlign:"center",color:t.sub,fontSize:13}}>No results found</div>}{filtered.map((item,i)=><button key={i} onClick={()=>{onNavigate(item.sectionId,item.tabId);onClose();}} style={{display:"flex",alignItems:"center",gap:10,width:"100%",padding:"10px 14px",background:"none",border:"none",borderBottom:`.5px solid ${t.sep}`,cursor:"pointer",textAlign:"left",fontFamily:FONT}}><span style={{fontSize:16}}>{item.tabLabel.split(" ")[0]}</span><div style={{flex:1}}><div style={{fontSize:13,fontWeight:600,color:t.text}}>{item.tabLabel.replace(/^[^\s]+\s/,"")}</div><div style={{fontSize:10,color:t.sub}}>{item.sectionLabel}</div></div><span style={{fontSize:10,color:t.sub,opacity:0.6}}>↵</span></button>)}</div><div style={{padding:"6px 14px",borderTop:`1px solid ${t.sep}`,display:"flex",gap:12,fontSize:10,color:t.sub,position:"relative"}}><SJMark size={18} style={{bottom:2,right:6,transform:"rotate(4deg)"}}/><span>↵ Navigate</span><span>ESC Close</span><span>⌘K Toggle</span></div></div></div>;}

