function mercProj(cLat,cLng,zoom,W,H){const ws=256*Math.pow(2,zoom),X=lng=>(lng+180)/360*ws,Y=lat=>{const s=Math.sin(lat*Math.PI/180);return(0.5-Math.log((1+s)/(1-s))/(4*Math.PI))*ws;},cx=X(cLng),cy=Y(cLat);return(lat,lng)=>({x:X(lng)-cx+W/2,y:Y(lat)-cy+H/2});}
function geoPath(d,fn){return d.replace(/(-?\d+(?:\.\d+)?)[ ,](-?\d+(?:\.\d+)?)/g,(m,a,b)=>{const p=fn(parseFloat(a),parseFloat(b));return p.x.toFixed(1)+" "+p.y.toFixed(1);});}
