// Complete months plus a live month-to-date point derived from the daily CASUALTIES
// array. Charts only — the KPI delta card and costPerKm intentionally keep using the
// raw complete-month series, since a partial month there would read as a real decline.
function ruMonthlyWithMTD(){
  const MON={Jan:"Jan",Feb:"Feb",Mar:"Mar",Apr:"Apr",May:"May",Jun:"Jun",Jul:"Jul",Aug:"Aug",Sep:"Sep",Oct:"Oct",Nov:"Nov",Dec:"Dec"};
  const base=HISTORICAL.ruCasualtiesMonthly;
  const latest=CASUALTIES[CASUALTIES.length-1];
  if(!latest) return base;
  const mon=MON[latest.date.split(" ")[0]];
  if(!mon||base.some(d=>d.m===mon)) return base;
  const days=CASUALTIES.filter(d=>d.date.startsWith(mon+" "));
  if(days.length<3) return base;
  return [...base,{m:mon,v:days.reduce((a,b)=>a+b.value,0),partial:true,days:days.length}];
}

function TrendChart({t,data,color,label,unit,desc,area,todayLabel,yDomain}){
  const Chart=area?AreaChart:LineChart;
  const partialIdx=data.findIndex(d=>d&&d.partial);
  const partialPt=partialIdx>=0?data[partialIdx]:null;
  return <Card t={t} style={{padding:"12px 8px 8px"}}>
    <div style={{padding:"0 8px 6px",display:"flex",alignItems:"baseline",justifyContent:"space-between"}}>
      <div style={{fontSize:12,fontWeight:700,color:t.text}}>{label}</div>
      <div style={{fontSize:10,color:t.sub}}>{unit}</div>
    </div>
    {todayLabel&&<div style={{padding:"0 8px 8px",fontSize:13,fontWeight:800,color:color}}>{todayLabel}</div>}
    <div style={{height:140}}>
      <ResponsiveContainer width="100%" height="100%">
        <Chart data={data} margin={{top:4,right:8,left:-12,bottom:0}}>
          <defs><linearGradient id={`g_${label.replace(/[^a-z]/gi,"")}`} x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor={color} stopOpacity={0.3}/><stop offset="95%" stopColor={color} stopOpacity={0}/></linearGradient></defs>
          <XAxis dataKey="m" tick={{fontSize:9,fill:t.sub}} tickLine={false} axisLine={false}/>
          <YAxis domain={yDomain||["auto","auto"]} tick={{fontSize:9,fill:t.sub}} tickLine={false} axisLine={false} width={38} tickFormatter={v=>v>=1000?`${(v/1000).toFixed(0)}k`:v}/>
          <Tooltip cursor={{stroke:color,strokeWidth:1,strokeDasharray:"4 3",opacity:0.65}} content={<TrendTooltip t={t} color={color} unit={unit}/>}/>
          {area?<Area type="monotone" dataKey="v" stroke={color} fill={`url(#g_${label.replace(/[^a-z]/gi,"")})`} strokeWidth={2} activeDot={{r:5,fill:color,stroke:t.isDark?"#0b1420":"#fff",strokeWidth:2}}/>:<Line type="monotone" dataKey="v" stroke={color} strokeWidth={2} dot={(p)=>p.index===partialIdx?<circle key={p.index} cx={p.cx} cy={p.cy} r={4} fill={t.card} stroke={color} strokeWidth={2} strokeDasharray="2 1.5"/>:<circle key={p.index} cx={p.cx} cy={p.cy} r={2.5} fill={color}/>} activeDot={{r:5,fill:color,stroke:t.isDark?"#0b1420":"#fff",strokeWidth:2}}/>}
        </Chart>
      </ResponsiveContainer>
    </div>
    {partialPt&&<div style={{fontSize:10,color:color,fontWeight:700,padding:"4px 8px 0",letterSpacing:".02em"}}>◌ {partialPt.m} is month-to-date ({partialPt.days??REPORT_NOW.getUTCDate()} days) — not a complete month, do not read as a decline</div>}
    {desc&&<div style={{fontSize:11,color:t.sub,lineHeight:1.5,padding:"6px 8px 2px"}}>{desc}</div>}
  </Card>;
}
function FuelComboChart({t,data,todayLabel,desc}){
  const tickGap=Math.max(0,Math.ceil(data.length/9)-1);
  return <Card t={t} style={{padding:"12px 8px 8px"}}>
    <div style={{padding:"0 8px 6px",display:"flex",alignItems:"baseline",justifyContent:"space-between"}}>
      <div style={{fontSize:12,fontWeight:700,color:t.text}}>US Gas &amp; Diesel — Last 90 Days</div>
    </div>
    {todayLabel&&<div style={{padding:"0 8px 8px",fontSize:12.5,fontWeight:800,color:t.text}}>{todayLabel}</div>}
    <div style={{height:180}}>
      <ResponsiveContainer width="100%" height="100%">
        <ComposedChart data={data} margin={{top:4,right:8,left:-6,bottom:0}}>
          <XAxis dataKey="m" tick={{fontSize:9,fill:t.sub}} tickLine={false} axisLine={false} interval={tickGap}/>
          <YAxis domain={[3,7]} tick={{fontSize:9,fill:t.sub}} tickLine={false} axisLine={false} width={30} tickFormatter={v=>`$${v}`}/>
          <Tooltip cursor={{stroke:t.sub,strokeWidth:1,strokeDasharray:"4 3",opacity:0.5}} content={<MultiTrendTooltip t={t}/>}/>
          <Legend wrapperStyle={{fontSize:10}} iconType="line" iconSize={14}/>
          <Line type="monotone" dataKey="gas" name="US Gas — National Avg ($/gal)" stroke="#0ea5e9" strokeWidth={2} dot={{r:2.5,fill:"#0ea5e9"}} activeDot={{r:5,stroke:t.isDark?"#0b1420":"#fff",strokeWidth:2}} connectNulls/>
          <Line type="monotone" dataKey="diesel" name="US Diesel — National Avg ($/gal)" stroke="#16a34a" strokeWidth={2} dot={{r:2.5,fill:"#16a34a"}} activeDot={{r:5,stroke:t.isDark?"#0b1420":"#fff",strokeWidth:2}} connectNulls/>
        </ComposedChart>
      </ResponsiveContainer>
    </div>
    {desc&&<div style={{fontSize:11,color:t.sub,lineHeight:1.5,padding:"6px 8px 2px"}}>{desc}</div>}
  </Card>;
}

